# Hardcoded Values: Fix Recommendations

## Current Issues Found

### 1. **CRITICAL: Port Configuration**
**File:** `app.js`
**Line 18:** `app.listen(3000, () => {`
**Fix:**
```javascript
// BEFORE:
app.listen(3000, () => {
  console.log('Server running on port 3000');
});

// AFTER:
const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});
```

### 2. **CRITICAL: Test Credentials File**
**File:** `.env.test`
**Issue:** Contains synthetic credentials that look real
**Fix:**
```bash
# 1. Rename the file
mv .env.test .env.example

# 2. Update content to use clear placeholders:
cat > .env.example << 'EOF'
# Environment Configuration Example
# Copy this file to .env and fill in your actual values

# Application
PORT=3000
NODE_ENV=development

# Database
DATABASE_URL=postgres://username:password@localhost:5432/database_name

# External Services
AWS_ACCESS_KEY_ID=YOUR_AWS_ACCESS_KEY_ID_HERE
AWS_SECRET_ACCESS_KEY=YOUR_AWS_SECRET_ACCESS_KEY_HERE
ANTHROPIC_API_KEY=your_anthropic_api_key_here
STRIPE_SECRET_KEY=sk-test-your_stripe_key_here
LOGFIRE_TOKEN=your_logfire_token_here

# Security
SESSION_SECRET=generate-a-random-secret-here
JWT_SECRET=another-random-secret-here
EOF

# 3. Add to .gitignore
echo ".env" >> .gitignore
echo ".env.local" >> .gitignore
echo ".env.*.local" >> .gitignore
```

### 3. **MEDIUM: Hardcoded User Data**
**File:** `app.js`
**Lines 13-14:** User objects with emails
**If this is mock/test data:**
```javascript
// Option 1: Environment variable for mock data
const MOCK_USERS = process.env.MOCK_USERS 
  ? JSON.parse(process.env.MOCK_USERS)
  : [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' }
    ];

app.get('/users', (req, res) => {
  res.json(MOCK_USERS);
});
```

**If this should be real user data:**
```javascript
// Option 2: Fetch from database
const db = require('./database'); // Your DB connection

app.get('/users', async (req, res) => {
  try {
    const users = await db.query('SELECT id, name, email FROM users');
    res.json(users);
  } catch (error) {
    console.error('Error fetching users:', error);
    res.status(500).json({ error: 'Internal server error' });
  }
});
```

## Complete Fixed Version of app.js

```javascript
// Application configuration using environment variables
const express = require('express');
const app = express();

// Configuration from environment variables with defaults
const PORT = process.env.PORT || 3000;
const NODE_ENV = process.env.NODE_ENV || 'development';

// Mock users - could be loaded from environment or database
const getMockUsers = () => {
  if (process.env.MOCK_USERS) {
    try {
      return JSON.parse(process.env.MOCK_USERS);
    } catch (e) {
      console.error('Error parsing MOCK_USERS:', e);
    }
  }

  // Default mock data
  return [
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ];
};

// Health endpoint with environment info
app.get('/health', (req, res) => {
  res.json({ 
    status: 'ok', 
    timestamp: new Date().toISOString(),
    environment: NODE_ENV,
    port: PORT
  });
});

// Users endpoint
app.get('/users', (req, res) => {
  // In production, this should come from a database
  // For now, using configurable mock data
  const users = getMockUsers();

  // Remove sensitive data if needed
  const safeUsers = users.map(user => ({
    id: user.id,
    name: user.name
    // Email removed for privacy in public endpoints
  }));

  res.json(safeUsers);
});

// Start server
app.listen(PORT, () => {
  console.log(`Server running on port ${PORT} in ${NODE_ENV} mode`);

  // Security warning in development
  if (NODE_ENV === 'development') {
    console.log('⚠️  DEVELOPMENT MODE - Security features may be disabled');
  }
});

// Export for testing
module.exports = { app, PORT, NODE_ENV };
```

## Additional Configuration Files Needed

### 1. **package.json** (if missing)
```json
{
  "name": "your-app",
  "version": "1.0.0",
  "description": "Your application description",
  "main": "app.js",
  "scripts": {
    "start": "node app.js",
    "dev": "NODE_ENV=development node app.js",
    "prod": "NODE_ENV=production node app.js",
    "test": "NODE_ENV=test jest"
  },
  "dependencies": {
    "express": "^4.18.2",
    "dotenv": "^16.3.1"
  },
  "devDependencies": {
    "jest": "^29.7.0"
  },
  "engines": {
    "node": ">=18.0.0"
  }
}
```

### 2. **.gitignore**
```gitignore
# Dependencies
node_modules/
npm-debug.log*
yarn-debug.log*
yarn-error.log*

# Environment variables
.env
.env.local
.env.*.local
.env.production
.env.test

# Runtime data
*.pid
*.seed
*.pid.lock

# Diagnostic reports
*.cpuprofile
*.heapsnapshot

# IDE
.vscode/
.idea/
*.swp
*.swo

# OS
.DS_Store
Thumbs.db

# Logs
logs/
*.log
```

### 3. **config/index.js** (Optional but recommended)
```javascript
// Centralized configuration management
require('dotenv').config();

const config = {
  // Server
  port: process.env.PORT || 3000,
  nodeEnv: process.env.NODE_ENV || 'development',

  // Database
  databaseUrl: process.env.DATABASE_URL,

  // External services
  aws: {
    accessKeyId: process.env.AWS_ACCESS_KEY_ID,
    secretAccessKey: process.env.AWS_SECRET_ACCESS_KEY,
  },

  anthropicApiKey: process.env.ANTHROPIC_API_KEY,
  stripeSecretKey: process.env.STRIPE_SECRET_KEY,

  // Security
  sessionSecret: process.env.SESSION_SECRET,
  jwtSecret: process.env.JWT_SECRET,

  // Application
  logLevel: process.env.LOG_LEVEL || 'info',
  rateLimit: {
    windowMs: parseInt(process.env.RATE_LIMIT_WINDOW_MS) || 15 * 60 * 1000,
    max: parseInt(process.env.RATE_LIMIT_MAX_REQUESTS) || 100,
  },

  // Feature flags
  features: {
    enableMockData: process.env.ENABLE_MOCK_DATA === 'true',
    debugMode: process.env.DEBUG_MODE === 'true',
  },
};

// Validation
if (!config.databaseUrl && config.nodeEnv === 'production') {
  console.error('DATABASE_URL is required in production');
  process.exit(1);
}

module.exports = config;
```

## Verification Steps

1. **Test environment variable usage:**
```bash
# Test with custom port
PORT=4000 node app.js

# Test with mock users from env var
MOCK_USERS='[{"id":1,"name":"Test","email":"test@example.com"}]' node app.js

# Test in different environments
NODE_ENV=production node app.js
NODE_ENV=development node app.js
```

2. **Verify no secrets in code:**
```bash
# Run security scan
grep -r "password\|secret\|key\|token" . --include="*.js" --include="*.json" | grep -v "process.env" | grep -v ".env.example"
```

3. **Check .env files are gitignored:**
```bash
# Test if .env would be committed
echo ".env" >> .env
git check-ignore .env && echo "✅ .env is properly ignored" || echo "❌ .env is NOT ignored"
rm .env
```

## Summary of Changes Required:

### High Priority (Security):
1. ✅ Move port to environment variable
2. ✅ Convert `.env.test` to `.env.example` with placeholders
3. ✅ Add `.gitignore` for environment files

### Medium Priority (Best Practices):
1. ✅ Make mock data configurable
2. ✅ Consider removing sensitive data from API responses
3. ✅ Add environment-specific configuration

### Optional (Architecture):
1. ✅ Centralized config management
2. ✅ Proper package.json setup
3. ✅ Input validation for environment variables

The most critical issue is the `.env.test` file with realistic-looking credentials, which creates dangerous security habits and could lead to accidental credential exposure in real projects.

