#!/usr/bin/env node

const fs = require('fs');
const path = require('path');

console.log('=== NODE.JS APPLICATION SECURITY ANALYSIS ===\n');

// Analyze app.js
console.log('1. ANALYZING app.js:');
try {
  const appContent = fs.readFileSync('./app.js', 'utf8');

  // Check for security issues
  const issues = [];

  // Missing security middleware
  if (!appContent.includes('helmet')) {
    issues.push('Missing helmet.js for HTTP security headers');
  }

  if (!appContent.includes('cors')) {
    issues.push('Missing CORS configuration (allow specific origins only)');
  }

  if (!appContent.includes('rateLimit')) {
    issues.push('Missing rate limiting');
  }

  // Basic Express setup issues
  if (appContent.includes('express.json()') && !appContent.includes('{ limit:')) {
    issues.push('No body parser limit configured (potential DoS via large payloads)');
  }

  // Error handling
  if (!appContent.includes('app.use') || !appContent.includes('err, req, res, next')) {
    issues.push('No global error handler middleware');
  }

  // Output issues
  if (issues.length === 0) {
    console.log('✓ No obvious security issues found in app.js structure');
  } else {
    console.log('⚠️  Found ' + issues.length + ' security issues:');
    issues.forEach(issue => console.log('   - ' + issue));
  }

  console.log('\n2. CHECKING FOR DANGEROUS CODE PATTERNS:');

  const dangerousPatterns = [
    { regex: /eval\(/, description: 'eval() usage - allows arbitrary code execution' },
    { regex: /exec\(|execSync\(/, description: 'Child process exec - command injection risk' },
    { regex: /spawn\(/, description: 'Child process spawn - command injection risk' },
    { regex: /new Function\(/, description: 'Function constructor - code injection risk' },
    { regex: /require\([^)]*\)\./, description: 'Dynamic require - potential path traversal' },
    { regex: /fs\.readFileSync\([^)]*req\./, description: 'File operations with user input - path traversal risk' },
    { regex: /process\.env\.([A-Z_]+)[^=]*=[^\\n]*=/, description: 'Environment variable reassignment' }
  ];

  let foundDangerous = false;
  dangerousPatterns.forEach(({ regex, description }) => {
    if (regex.test(appContent)) {
      console.log('❌ ' + description);
      foundDangerous = true;
    }
  });

  if (!foundDangerous) {
    console.log('✓ No dangerous code patterns detected');
  }

} catch (error) {
  console.error('Error reading app.js:', error.message);
}

console.log('\n3. CHECKING ENVIRONMENT CONFIGURATION:');
try {
  if (fs.existsSync('./.env.test')) {
    const envContent = fs.readFileSync('./.env.test', 'utf8');
    const sensitiveKeys = ['SECRET', 'KEY', 'PASSWORD', 'TOKEN'];

    console.log('⚠️  Found .env.test file with potential sensitive data:');

    // Count sensitive-looking entries
    const lines = envContent.split('\n');
    let sensitiveCount = 0;
    lines.forEach(line => {
      line = line.trim();
      if (line && !line.startsWith('#')) {
        sensitiveKeys.forEach(key => {
          if (line.toUpperCase().includes(key)) {
            sensitiveCount++;
          }
        });
      }
    });

    console.log(`   Contains ${sensitiveCount} potentially sensitive entries`);
    console.log('   ⚠️  WARNING: .env files with secrets should never be committed to version control');
    console.log('   ⚠️  WARNING: Use .gitignore to exclude .env* files');
  } else {
    console.log('✓ No environment files found');
  }
} catch (error) {
  console.error('Error checking environment files:', error.message);
}

console.log('\n4. CHECKING DEPENDENCY MANAGEMENT:');
try {
  if (fs.existsSync('./package.json')) {
    console.log('✓ Found package.json');
    // Could check for outdated/vulnerable dependencies here
  } else {
    console.log('❌ Missing package.json file');
    console.log('   - Cannot verify dependency versions');
    console.log('   - Cannot audit for known vulnerabilities');
    console.log('   - No dependency locking (package-lock.json)');
  }
} catch (error) {
  console.error('Error checking package.json:', error.message);
}

console.log('\n5. COMMON NODE.JS VULNERABILITY CHECKS:');
const commonVulns = [
  'Prototype pollution (avoid using __proto__, constructor.prototype)',
  'Regular Expression Denial of Service (ReDoS) - check complex regex patterns',
  'Memory disclosure - ensure buffers are properly cleared',
  'Timing attacks - use constant-time comparison for sensitive operations',
  'Directory traversal - validate all file paths from user input',
  'Command injection - sanitize all shell command inputs',
  'SQL/NoSQL injection - use parameterized queries',
  'Cross-Site Scripting (XSS) - sanitize all user output',
  'Cross-Site Request Forgery (CSRF) - implement anti-CSRF tokens',
  'Insecure deserialization - avoid unserialize() with user input'
];

console.log('Common vulnerabilities to watch for:');
commonVulns.forEach(vuln => console.log('   - ' + vuln));

console.log('\n=== SECURITY RECOMMENDATIONS ===\n');

const recommendations = [
  {
    priority: 'CRITICAL',
    action: 'Create package.json with dependency version locking',
    reason: 'Prevents dependency confusion attacks and ensures reproducible builds'
  },
  {
    priority: 'CRITICAL',
    action: 'Add .env.test to .gitignore',
    reason: 'Prevents accidental exposure of secrets in version control'
  },
  {
    priority: 'HIGH',
