    reason: 'Prevents injection attacks (SQLi, XSS, command injection)'
  },
  {
    priority: 'HIGH',
    action: 'Implement proper error handling',
    reason: 'Prevents information leakage through error messages'
  },
  {
    priority: 'MEDIUM',
    action: 'Add CORS configuration',
    reason: 'Restricts cross-origin requests to trusted origins only'
  },
  {
    priority: 'MEDIUM',
    action: 'Implement rate limiting',
    reason: 'Prevents brute force and DoS attacks'
  },
  {
    priority: 'MEDIUM',
    action: 'Add audit logging',
    reason: 'Enables security monitoring and incident response'
  },
  {
    priority: 'LOW',
    action: 'Use environment-specific configuration',
    reason: 'Separates configuration from code for different environments'
  }
];

recommendations.forEach(rec => {
  console.log(`${rec.priority}: ${rec.action}`);
  console.log(`   ${rec.reason}\n`);
});

console.log('=== NEXT STEPS ===');
console.log('1. Run: npm init -y');
console.log('2. Run: npm install express helmet cors express-rate-limit');
