// Secure Express application with security best practices
const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');

const app = express();

// ================= SECURITY MIDDLEWARE =================

// 1. Helmet.js for HTTP security headers
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      styleSrc: ["'self'", "'unsafe-inline'"],
      scriptSrc: ["'self'"],
      imgSrc: ["'self'", "data:", "https:"],
      connectSrc: ["'self'"],
      fontSrc: ["'self'"],
      objectSrc: ["'none'"],
      mediaSrc: ["'self'"],
      frameSrc: ["'none'"],
    },
  },
  hsts: {
    maxAge: 31536000, // 1 year
    includeSubDomains: true,
    preload: true
  },
  frameguard: { action: 'deny' },
  referrerPolicy: { policy: 'strict-origin-when-cross-origin' }
}));

// 2. CORS configuration (restrict to specific origins in production)
const corsOptions = {
  origin: process.env.NODE_ENV === 'production' 
    ? ['https://yourdomain.com'] // Add your production domains
    : ['http://localhost:3000', 'http://localhost:8080'], // Development
  methods: ['GET', 'POST', 'PUT', 'DELETE', 'OPTIONS'],
  allowedHeaders: ['Content-Type', 'Authorization'],
  credentials: true,
  maxAge: 86400 // 24 hours
};
app.use(cors(corsOptions));

// 3. Rate limiting to prevent brute force and DoS attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: { error: 'Too many requests, please try again later.' },
  standardHeaders: true, // Return rate limit info in the `RateLimit-*` headers
  legacyHeaders: false, // Disable the `X-RateLimit-*` headers
});

// Apply rate limiting to all requests
app.use(limiter);

// 4. Body parser with size limits to prevent DoS via large payloads
app.use(express.json({ limit: '10kb' })); // JSON body limit
app.use(express.urlencoded({ extended: true, limit: '10kb' })); // URL-encoded body limit

// ================= INPUT VALIDATION =================

// Simple validation middleware example
const validateUserRequest = (req, res, next) => {
  // In a real application, use a validation library like Joi or express-validator
  const { name, email } = req.body;

  if (req.method === 'POST' || req.method === 'PUT') {
    if (!name || typeof name !== 'string' || name.length > 100) {
      return res.status(400).json({ 
        error: 'Invalid name. Must be a string under 100 characters.' 
      });
    }

    // Simple email validation
    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    if (!email || !emailRegex.test(email)) {
      return res.status(400).json({ 
        error: 'Invalid email format.' 
      });
    }
  }

  next();
};

// ================= ROUTES =================

// Health check endpoint (no auth required)
app.get('/health', (req, res) => {
  res.json({ 
    status: 'ok', 
    timestamp: new Date().toISOString(),
    environment: process.env.NODE_ENV || 'development'
  });
});

// Users endpoint with basic validation
app.get('/users', (req, res) => {
  // In a real app, validate query parameters
  const { limit = 10, offset = 0 } = req.query;

  // Validate query params
  const parsedLimit = parseInt(limit, 10);
  const parsedOffset = parseInt(offset, 10);

  if (isNaN(parsedLimit) || parsedLimit < 1 || parsedLimit > 100) {
    return res.status(400).json({ error: 'Limit must be between 1 and 100' });
  }

  if (isNaN(parsedOffset) || parsedOffset < 0) {
    return res.status(400).json({ error: 'Offset must be a positive number' });
  }

  // Sanitize output to prevent XSS
  const users = [
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ];

  res.json(users);
});

// Example POST endpoint with validation
app.post('/users', validateUserRequest, (req, res) => {
  // In a real application, this would create a user
  const { name, email } = req.body;

  // Sanitize and create user (in memory example)
  const newUser = {
    id: Date.now(),
    name: name.trim(), // Basic sanitization
    email: email.toLowerCase().trim(),
    createdAt: new Date().toISOString()
  };

  res.status(201).json(newUser);
});

// ================= ERROR HANDLING =================

// 404 handler
app.use((req, res, next) => {
  res.status(404).json({ 
    error: 'Not Found',
    path: req.path,
    method: req.method
  });
});

// Global error handler - prevent information leakage
app.use((err, req, res, next) => {
  console.error('Error:', {
    message: err.message,
    stack: process.env.NODE_ENV === 'development' ? err.stack : undefined,
    path: req.path,
    method: req.method,
    timestamp: new Date().toISOString()
  });

  const statusCode = err.status || err.statusCode || 500;
  const response = {
    error: 'Internal Server Error',
    requestId: req.id || Date.now().toString(36) + Math.random().toString(36).substr(2)
  };

  // Only show error details in development
  if (process.env.NODE_ENV === 'development') {
    response.message = err.message;
    response.stack = err.stack;
  }

  res.status(statusCode).json(response);
});

// ================= SECURE SERVER CONFIGURATION =================

const port = process.env.PORT || 3000;
const host = process.env.HOST || '0.0.0.0';

const server = app.listen(port, host, () => {
  console.log(`Secure server running on http://${host}:${port}`);
  console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
  console.log('Security features enabled:');
  console.log('  - Helmet.js HTTP security headers');
  console.log('  - CORS with origin restrictions');
  console.log('  - Rate limiting (100 requests/15min per IP)');
  console.log('  - Input validation middleware');
  console.log('  - Global error handling');
});

// Graceful shutdown
process.on('SIGTERM', () => {
  console.log('SIGTERM received. Shutting down gracefully...');
  server.close(() => {
    console.log('Server closed');
    process.exit(0);
  });
});

process.on('SIGINT', () => {
  console.log('SIGINT received. Shutting down gracefully...');
  server.close(() => {
    console.log('Server closed');
    process.exit(0);
  });
});

module.exports = app;

