// Fully configurable Express application with all values in environment variables
const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');

const app = express();

// ================= CONFIGURATION =================

// Parse environment variables with sensible defaults
const config = {
  server: {
    port: parseInt(process.env.PORT || '3000', 10),
    host: process.env.HOST || '0.0.0.0',
    environment: process.env.NODE_ENV || 'development',
    appName: process.env.APP_NAME || 'Secure Express App',
  },

  cors: {
    // Parse origins from environment variables
    origins: (() => {
      try {
        if (process.env.NODE_ENV === 'production') {
          return process.env.ALLOWED_ORIGINS 
            ? JSON.parse(process.env.ALLOWED_ORIGINS)
            : []; // Empty array in production if not specified
        } else {
          return process.env.DEV_ORIGINS
            ? JSON.parse(process.env.DEV_ORIGINS)
            : ['http://localhost:3000', 'http://localhost:8080'];
        }
      } catch (error) {
        console.error('Error parsing CORS origins from environment variables:', error.message);
        return process.env.NODE_ENV === 'production' ? [] : ['http://localhost:3000'];
      }
    })(),

    methods: process.env.CORS_METHODS 
      ? JSON.parse(process.env.CORS_METHODS)
      : ['GET', 'POST', 'PUT', 'DELETE', 'OPTIONS'],

    allowedHeaders: process.env.CORS_ALLOWED_HEADERS
      ? JSON.parse(process.env.CORS_ALLOWED_HEADERS)
      : ['Content-Type', 'Authorization'],

    credentials: process.env.CORS_CREDENTIALS !== 'false', // Defaults to true
    maxAge: parseInt(process.env.CORS_MAX_AGE || '86400', 10), // 24 hours
  },

  rateLimit: {
    windowMs: parseInt(process.env.RATE_LIMIT_WINDOW_MS || '900000', 10), // 15 minutes
    max: parseInt(process.env.RATE_LIMIT_MAX_REQUESTS || '100', 10),
    message: process.env.RATE_LIMIT_MESSAGE 
      ? JSON.parse(process.env.RATE_LIMIT_MESSAGE)
      : { error: 'Too many requests, please try again later.' },
    standardHeaders: process.env.RATE_LIMIT_STANDARD_HEADERS !== 'false', // Defaults to true
    legacyHeaders: process.env.RATE_LIMIT_LEGACY_HEADERS === 'true', // Defaults to false
  },

  security: {
    bodyLimit: process.env.BODY_LIMIT || '10kb',
    hstsMaxAge: parseInt(process.env.HSTS_MAX_AGE || '31536000', 10), // 1 year
    hstsIncludeSubDomains: process.env.HSTS_INCLUDE_SUBDOMAINS !== 'false', // Defaults to true
    hstsPreload: process.env.HSTS_PRELOAD === 'true', // Defaults to false
  },

  logging: {
    level: process.env.LOG_LEVEL || 'info',
    format: process.env.LOG_FORMAT || 'combined',
  },
};

// Validate configuration
if (config.server.environment === 'production') {
  if (config.cors.origins.length === 0) {
    console.warn('⚠️  WARNING: No ALLOWED_ORIGINS specified for production environment');
    console.warn('   Consider setting ALLOWED_ORIGINS environment variable');
  }

  if (config.rateLimit.max > 1000) {
    console.warn('⚠️  WARNING: Rate limit max requests is very high for production');
  }
}

// Log configuration (mask sensitive values in production)
if (config.server.environment === 'development') {
  console.log('Application Configuration:');
  console.log(JSON.stringify(config, null, 2));
}

// ================= SECURITY MIDDLEWARE =================

// 1. Helmet.js with configurable options
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      styleSrc: ["'self'", "'unsafe-inline'"],
      scriptSrc: ["'self'"],
      imgSrc: ["'self'", "data:", "https:"],
      connectSrc: ["'self'"],
      fontSrc: ["'self'"],
      objectSrc: ["'none'"],
      mediaSrc: ["'self'"],
      frameSrc: ["'none'"],
    },
  },
  hsts: {
    maxAge: config.security.hstsMaxAge,
    includeSubDomains: config.security.hstsIncludeSubDomains,
    preload: config.security.hstsPreload,
  },
  frameguard: { action: 'deny' },
  referrerPolicy: { policy: 'strict-origin-when-cross-origin' }
}));

// 2. CORS with environment-based configuration
app.use(cors({
  origin: config.cors.origins,
  methods: config.cors.methods,
  allowedHeaders: config.cors.allowedHeaders,
  credentials: config.cors.credentials,
  maxAge: config.cors.maxAge,
}));

// 3. Rate limiting with configurable settings
const limiter = rateLimit({
  windowMs: config.rateLimit.windowMs,
  max: config.rateLimit.max,
  message: config.rateLimit.message,
  standardHeaders: config.rateLimit.standardHeaders,
  legacyHeaders: config.rateLimit.legacyHeaders,
});

app.use(limiter);

// 4. Body parser with configurable limits
app.use(express.json({ limit: config.security.bodyLimit }));
app.use(express.urlencoded({ 
  extended: true, 
  limit: config.security.bodyLimit 
}));

// ================= INPUT VALIDATION =================

// Configurable validation settings
const validationConfig = {
  maxNameLength: parseInt(process.env.MAX_NAME_LENGTH || '100', 10),
  maxEmailLength: parseInt(process.env.MAX_EMAIL_LENGTH || '255', 10),
  passwordMinLength: parseInt(process.env.PASSWORD_MIN_LENGTH || '8', 10),
};

const validateUserRequest = (req, res, next) => {
  const { name, email } = req.body;

  if (req.method === 'POST' || req.method === 'PUT') {
    if (!name || typeof name !== 'string' || name.length > validationConfig.maxNameLength) {
      return res.status(400).json({ 
        error: `Invalid name. Must be a string under ${validationConfig.maxNameLength} characters.` 
      });
    }

    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    if (!email || !emailRegex.test(email) || email.length > validationConfig.maxEmailLength) {
      return res.status(400).json({ 
        error: `Invalid email format or too long (max ${validationConfig.maxEmailLength} chars).` 
      });
    }
  }

  next();
};

// ================= ROUTES =================

// Health check endpoint with configurable response
app.get('/health', (req, res) => {
  const healthResponse = {
    status: 'ok',
    timestamp: new Date().toISOString(),
    environment: config.server.environment,
    app: config.server.appName,
    uptime: process.uptime(),
    memory: process.memoryUsage(),
  };

  // Add version if specified
  if (process.env.APP_VERSION) {
    healthResponse.version = process.env.APP_VERSION;
  }

  // Add commit hash if specified
  if (process.env.COMMIT_HASH) {
    healthResponse.commit = process.env.COMMIT_HASH;
  }

  res.json(healthResponse);
});

// Users endpoint - sample data could come from environment or database
app.get('/users', (req, res) => {
  const { limit = 10, offset = 0 } = req.query;

  // Parse and validate with configurable limits
  const maxLimit = parseInt(process.env.MAX_QUERY_LIMIT || '100', 10);
  const parsedLimit = Math.min(parseInt(limit, 10) || 10, maxLimit);
  const parsedOffset = Math.max(parseInt(offset, 10) || 0, 0);

  // Sample data - in real app, this would come from database
  // Could also be loaded from environment variable for sample data
  const users = [
    { 
      id: 1, 
      name: 'Alice', 
      email: 'alice@example.com',
      // These could be from environment variables for demo data
      role: process.env.DEMO_USER_ROLE || 'user',
      status: process.env.DEMO_USER_STATUS || 'active'
    },
    { 
      id: 2, 
      name: 'Bob', 
      email: 'bob@example.com',
      role: process.env.DEMO_USER_ROLE || 'user',
      status: process.env.DEMO_USER_STATUS || 'active'
    },
  ].slice(parsedOffset, parsedOffset + parsedLimit);

  res.json({
    data: users,
    pagination: {
      limit: parsedLimit,
      offset: parsedOffset,
      total: users.length,
      maxLimit: maxLimit,
    }
  });
});

// Example POST endpoint with validation
app.post('/users', validateUserRequest, (req, res) => {
  const { name, email } = req.body;

  // Create timestamp with configurable format
  const timestamp = new Date().toISOString();

  const newUser = {
    id: Date.now(),
    name: name.trim(),
    email: email.toLowerCase().trim(),
    createdAt: timestamp,
    // Environment variable for default user role
    role: process.env.DEFAULT_USER_ROLE || 'user',
  };

  res.status(201).json({
    message: 'User created successfully',
    data: newUser,
    links: {
      self: `/users/${newUser.id}`,
      all: '/users',
    }
  });
});

// ================= ERROR HANDLING =================

// Configurable error handling
app.use((req, res, next) => {
  res.status(404).json({ 
    error: 'Not Found',
    path: req.path,
    method: req.method,
    timestamp: new Date().toISOString(),
  });
});

// Global error handler
app.use((err, req, res, next) => {
  const errorId = Date.now().toString(36) + Math.random().toString(36).substr(2);

  // Configurable logging level
  if (config.logging.level === 'debug' || config.server.environment === 'development') {
    console.error('Error:', {
      id: errorId,
      message: err.message,
      stack: err.stack,
      path: req.path,
      method: req.method,
      timestamp: new Date().toISOString(),
    });
  } else {
    console.error('Error:', {
      id: errorId,
      message: err.message,
      path: req.path,
      timestamp: new Date().toISOString(),
    });
  }

  const statusCode = err.status || err.statusCode || 500;
  const response = {
    error: 'Internal Server Error',
    requestId: req.id || errorId,
    timestamp: new Date().toISOString(),
  };

  // Only show detailed errors in development
  if (config.server.environment === 'development') {
    response.message = err.message;
    if (config.logging.level === 'debug') {
      response.stack = err.stack;
    }
  }

  res.status(statusCode).json(response);
});

// ================= SERVER STARTUP =================

const server = app.listen(config.server.port, config.server.host, () => {
  console.log(`
========================================
${config.server.appName}
========================================
Environment: ${config.server.environment}
Server: http://${config.server.host}:${config.server.port}
========================================
Security Features:
  - Helmet.js HTTP security headers
  - CORS: ${config.cors.origins.length} allowed origin(s)
  - Rate limiting: ${config.rateLimit.max} requests per ${config.rateLimit.windowMs / 60000} minutes
  - Body limit: ${config.security.bodyLimit}
========================================
Log Level: ${config.logging.level}
========================================
  `);
});

// Graceful shutdown with configurable timeout
const shutdownTimeout = parseInt(process.env.SHUTDOWN_TIMEOUT || '30000', 10);

const gracefulShutdown = (signal) => {
  console.log(`\n${signal} received. Starting graceful shutdown...`);

  server.close(() => {
    console.log('HTTP server closed');
    process.exit(0);
  });

  // Force shutdown after timeout
  setTimeout(() => {
    console.error('Could not close connections in time, forcefully shutting down');
    process.exit(1);
  }, shutdownTimeout);
};

process.on('SIGTERM', () => gracefulShutdown('SIGTERM'));
process.on('SIGINT', () => gracefulShutdown('SIGINT'));

// Handle uncaught exceptions
process.on('uncaughtException', (error) => {
  console.error('Uncaught Exception:', error);
  gracefulShutdown('uncaughtException');
});

process.on('unhandledRejection', (reason, promise) => {
  console.error('Unhandled Rejection at:', promise, 'reason:', reason);
});

module.exports = { app, config, server };

