// Secure Express application with all hardcoded values moved to environment variables
const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const cors = require('cors');

const app = express();

// ========== CONFIGURATION FROM ENVIRONMENT VARIABLES ==========
const config = {
  // Server configuration
  port: process.env.PORT || 3000,
  nodeEnv: process.env.NODE_ENV || 'development',
  host: process.env.HOST || 'localhost',

  // Security configuration
  rateLimitWindowMs: parseInt(process.env.RATE_LIMIT_WINDOW_MS) || 15 * 60 * 1000, // 15 minutes default
  rateLimitMaxRequests: parseInt(process.env.RATE_LIMIT_MAX_REQUESTS) || 100,
  bodyParserLimit: process.env.BODY_PARSER_LIMIT || '10kb',

  // CORS configuration
  allowedOrigins: process.env.ALLOWED_ORIGINS ? 
    process.env.ALLOWED_ORIGINS.split(',') : 
    ['http://localhost:3000'],

  // Feature flags
  enableRateLimiting: process.env.ENABLE_RATE_LIMITING !== 'false', // true by default
  enableCors: process.env.ENABLE_CORS !== 'false', // true by default
  enableLogging: process.env.ENABLE_LOGGING !== 'false', // true by default
  debugMode: process.env.DEBUG_MODE === 'true', // false by default
};

// Log configuration in development/debug mode
if (config.nodeEnv === 'development' || config.debugMode) {
  console.log('Application configuration:', {
    port: config.port,
    nodeEnv: config.nodeEnv,
    rateLimit: {
      enabled: config.enableRateLimiting,
      windowMs: config.rateLimitWindowMs,
      max: config.rateLimitMaxRequests
    },
    cors: {
      enabled: config.enableCors,
      origins: config.allowedOrigins
    }
  });
}

// 1. Security headers with Helmet
app.use(helmet());

// 2. CORS configuration - only if enabled
if (config.enableCors) {
  const corsOptions = {
    origin: config.allowedOrigins,
    optionsSuccessStatus: 200
  };
  app.use(cors(corsOptions));
}

// 3. Rate limiting - only if enabled
if (config.enableRateLimiting) {
  const limiter = rateLimit({
    windowMs: config.rateLimitWindowMs,
    max: config.rateLimitMaxRequests,
    message: process.env.RATE_LIMIT_MESSAGE || 'Too many requests from this IP, please try again later.',
    standardHeaders: true,
    legacyHeaders: false,
  });
  app.use(limiter);
}

// 4. Body parsing with configurable size limits
app.use(express.json({ limit: config.bodyParserLimit }));
app.use(express.urlencoded({ extended: true, limit: config.bodyParserLimit }));

// 5. Request logging middleware - only if enabled
if (config.enableLogging) {
  app.use((req, res, next) => {
    console.log(`${new Date().toISOString()} - ${req.method} ${req.url} - ${req.ip}`);
    next();
  });
}

// Health endpoint - shows current configuration
app.get('/health', (req, res) => {
  const healthInfo = {
    status: 'ok',
    timestamp: new Date().toISOString(),
    environment: config.nodeEnv,
    service: 'express-api',
    version: process.env.APP_VERSION || '1.0.0',
    uptime: process.uptime(),

    // Configuration info (limited in production)
    config: config.nodeEnv === 'production' ? {
      rateLimiting: config.enableRateLimiting,
      cors: config.enableCors,
      logging: config.enableLogging
    } : {
      port: config.port,
      rateLimiting: {
        enabled: config.enableRateLimiting,
        windowMs: config.rateLimitWindowMs,
        max: config.rateLimitMaxRequests
      },
      cors: {
        enabled: config.enableCors,
        origins: config.allowedOrigins
      }
    }
  };

  res.json(healthInfo);
});

// Users endpoint with configurable limits
app.get('/users', (req, res) => {
  const { limit } = req.query;
  const maxLimit = parseInt(process.env.USER_MAX_LIMIT) || 100;
  const defaultLimit = parseInt(process.env.USER_DEFAULT_LIMIT) || 10;

  // Input validation
  if (limit) {
    const limitNum = Number(limit);
    if (!Number.isInteger(limitNum) || limitNum < 1 || limitNum > maxLimit) {
      return res.status(400).json({ 
        error: `Invalid limit parameter. Must be an integer between 1 and ${maxLimit}.` 
      });
    }
  }

  // In a real application, this would come from a database
  // For demo purposes, returning mock data
  const users = [
    { id: 1, name: 'User 1', email: process.env.DEMO_EMAIL_1 || 'user1@example.com' },
    { id: 2, name: 'User 2', email: process.env.DEMO_EMAIL_2 || 'user2@example.com' },
  ];

  res.json({
    users,
    pagination: {
      total: users.length,
      limit: limit ? Number(limit) : defaultLimit,
      maxLimit
    }
  });
});

// 6. Error handling middleware with configurable error messages
app.use((err, req, res, next) => {
  if (config.enableLogging) {
    console.error('Error:', {
      message: err.message,
      stack: config.debugMode ? err.stack : undefined,
      url: req.url,
      method: req.method,
      ip: req.ip,
      timestamp: new Date().toISOString()
    });
  }

  res.status(err.status || 500).json({
    error: config.nodeEnv === 'production' ? 
      (process.env.PRODUCTION_ERROR_MESSAGE || 'Internal server error') : 
      err.message,
    ...(config.debugMode && { stack: err.stack })
  });
});

// 7. 404 handler with configurable message
app.use((req, res) => {
  res.status(404).json({ 
    error: process.env.NOT_FOUND_MESSAGE || 'Resource not found',
    path: req.path,
    method: req.method
  });
});

// Start server with configurable port
const server = app.listen(config.port, config.host, () => {
  console.log(`
  ========================================
  Server Information:
  Environment: ${config.nodeEnv}
  Server: http://${config.host}:${config.port}
  Rate Limiting: ${config.enableRateLimiting ? 'Enabled' : 'Disabled'}
  CORS: ${config.enableCors ? 'Enabled' : 'Disabled'}
  Logging: ${config.enableLogging ? 'Enabled' : 'Disabled'}
  ========================================
  `);
});

// 8. Graceful shutdown with configurable timeout
const shutdownGracefully = (signal) => {
  console.log(`\n${signal} received: starting graceful shutdown...`);

  const shutdownTimeout = parseInt(process.env.SHUTDOWN_TIMEOUT_MS) || 10000;

  server.close(() => {
    console.log('HTTP server closed');
    process.exit(0);
  });

  // Force shutdown after timeout
  setTimeout(() => {
    console.error('Could not close connections in time, forcefully shutting down');
    process.exit(1);
  }, shutdownTimeout);
};

process.on('SIGTERM', () => shutdownGracefully('SIGTERM'));
process.on('SIGINT', () => shutdownGracefully('SIGINT'));

module.exports = { app, server, config };

// Final secure application with all configuration moved to environment variables

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const cors = require('cors');
const dotenv = require('dotenv');

// Load environment variables from .env file
dotenv.config();

// ========== CONFIGURATION ==========
const config = {
  // Server
  PORT: process.env.PORT || 3000,
  HOST: process.env.HOST || 'localhost',
  NODE_ENV: process.env.NODE_ENV || 'development',

  // Security
  RATE_LIMIT_WINDOW_MS: parseInt(process.env.RATE_LIMIT_WINDOW_MS) || (15 * 60 * 1000), // 15 minutes
  RATE_LIMIT_MAX_REQUESTS: parseInt(process.env.RATE_LIMIT_MAX_REQUESTS) || 100,
  RATE_LIMIT_MESSAGE: process.env.RATE_LIMIT_MESSAGE || 'Too many requests from this IP, please try again later.',
  BODY_PARSER_LIMIT: process.env.BODY_PARSER_LIMIT || '10kb',

  // CORS
  ALLOWED_ORIGINS: process.env.ALLOWED_ORIGINS 
    ? process.env.ALLOWED_ORIGINS.split(',') 
    : ['http://localhost:3000'],

  // Feature flags
  ENABLE_RATE_LIMITING: process.env.ENABLE_RATE_LIMITING !== 'false',
  ENABLE_CORS: process.env.ENABLE_CORS !== 'false',
  ENABLE_LOGGING: process.env.ENABLE_LOGGING !== 'false',
  DEBUG_MODE: process.env.DEBUG_MODE === 'true',

  // Application
  APP_NAME: process.env.APP_NAME || 'Secure Express API',
  APP_VERSION: process.env.APP_VERSION || '1.0.0',
  SHUTDOWN_TIMEOUT_MS: parseInt(process.env.SHUTDOWN_TIMEOUT_MS) || 10000,

  // API Configuration
  USER_MAX_LIMIT: parseInt(process.env.USER_MAX_LIMIT) || 100,
  USER_DEFAULT_LIMIT: parseInt(process.env.USER_DEFAULT_LIMIT) || 10,

  // Error Messages
  PRODUCTION_ERROR_MESSAGE: process.env.PRODUCTION_ERROR_MESSAGE || 'Internal server error',
  NOT_FOUND_MESSAGE: process.env.NOT_FOUND_MESSAGE || 'Resource not found'
};

// Validate required environment variables in production
if (config.NODE_ENV === 'production') {
  const required = ['PORT', 'ALLOWED_ORIGINS'];
  const missing = required.filter(key => !process.env[key]);

  if (missing.length > 0) {
    console.error(`Missing required environment variables in production: ${missing.join(', ')}`);
    process.exit(1);
  }
}

// Log configuration in non-production environments
if (config.NODE_ENV !== 'production' || config.DEBUG_MODE) {
  console.log('🚀 Application Configuration:');
  console.log(`   Environment: ${config.NODE_ENV}`);
  console.log(`   Server: http://${config.HOST}:${config.PORT}`);
  console.log(`   Rate Limiting: ${config.ENABLE_RATE_LIMITING ? 'Enabled' : 'Disabled'}`);
  console.log(`   CORS: ${config.ENABLE_CORS ? 'Enabled' : 'Disabled'}`);
  console.log(`   Logging: ${config.ENABLE_LOGGING ? 'Enabled' : 'Disabled'}`);
  console.log(`   Debug Mode: ${config.DEBUG_MODE ? 'Enabled' : 'Disabled'}`);
}

const app = express();

// ========== MIDDLEWARE SETUP ==========

// 1. Security headers
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      styleSrc: ["'self'", "'unsafe-inline'"],
      imgSrc: ["'self'", "data:", "https:"],
      scriptSrc: ["'self'"],
      fontSrc: ["'self'"]
    }
  }
}));

// 2. CORS with environment-based configuration
if (config.ENABLE_CORS) {
  const corsOptions = {
    origin: function (origin, callback) {
      if (!origin || config.ALLOWED_ORIGINS.includes(origin)) {
        callback(null, true);
      } else {
        callback(new Error('Not allowed by CORS'));
      }
    },
    credentials: true,
    optionsSuccessStatus: 200
  };
  app.use(cors(corsOptions));
}

// 3. Rate limiting
if (config.ENABLE_RATE_LIMITING) {
  const limiter = rateLimit({
    windowMs: config.RATE_LIMIT_WINDOW_MS,
    max: config.RATE_LIMIT_MAX_REQUESTS,
    message: config.RATE_LIMIT_MESSAGE,
    standardHeaders: true,
    legacyHeaders: false,
    skipSuccessfulRequests: config.NODE_ENV === 'development' // Skip rate limiting for successful requests in dev
  });
  app.use(limiter);
}

// 4. Body parsing with configurable limits
app.use(express.json({ limit: config.BODY_PARSER_LIMIT }));
app.use(express.urlencoded({ 
  extended: true, 
  limit: config.BODY_PARSER_LIMIT 
}));

// 5. Request logging
if (config.ENABLE_LOGGING) {
  const morgan = require('morgan');
  const logFormat = config.NODE_ENV === 'production' ? 'combined' : 'dev';
  app.use(morgan(logFormat));
}

// ========== ROUTES ==========

// Health check endpoint
app.get('/health', (req, res) => {
  const healthData = {
    status: 'healthy',
    timestamp: new Date().toISOString(),
    service: config.APP_NAME,
    version: config.APP_VERSION,
    environment: config.NODE_ENV,
    uptime: process.uptime(),

    // System info
    nodeVersion: process.version,
    platform: process.platform,

    // Configuration (limited in production)
    config: config.NODE_ENV === 'production' ? {
      rateLimiting: config.ENABLE_RATE_LIMITING,
      cors: config.ENABLE_CORS
    } : {
      port: config.PORT,
      host: config.HOST,
      rateLimiting: {
        enabled: config.ENABLE_RATE_LIMITING,
        windowMs: config.RATE_LIMIT_WINDOW_MS,
        max: config.RATE_LIMIT_MAX_REQUESTS
      },
      cors: {
        enabled: config.ENABLE_CORS,
        origins: config.ALLOWED_ORIGINS
      }
    }
  };

  res.json(healthData);
});

// Users endpoint with configurable pagination
app.get('/users', (req, res) => {
  const { limit = config.USER_DEFAULT_LIMIT, page = 1 } = req.query;

  // Validate inputs
  const limitNum = Number(limit);
  const pageNum = Number(page);

  if (!Number.isInteger(limitNum) || limitNum < 1 || limitNum > config.USER_MAX_LIMIT) {
    return res.status(400).json({
      error: `Invalid limit parameter. Must be an integer between 1 and ${config.USER_MAX_LIMIT}.`
    });
  }

  if (!Number.isInteger(pageNum) || pageNum < 1) {
    return res.status(400).json({
      error: 'Invalid page parameter. Must be a positive integer.'
    });
  }

  // Mock data - in real app, this would come from database
  const mockUsers = Array.from({ length: 50 }, (_, i) => ({
    id: i + 1,
    name: `User ${i + 1}`,
    email: `user${i + 1}@${process.env.DEMO_EMAIL_DOMAIN || 'example.com'}`,
    createdAt: new Date(Date.now() - i * 86400000).toISOString() // Mock dates
  }));

  // Implement simple pagination
  const startIdx = (pageNum - 1) * limitNum;
  const endIdx = startIdx + limitNum;
  const users = mockUsers.slice(startIdx, endIdx);

  res.json({
    data: users,
    pagination: {
      page: pageNum,
      limit: limitNum,
      total: mockUsers.length,
      totalPages: Math.ceil(mockUsers.length / limitNum),
      hasNextPage: endIdx < mockUsers.length,
      hasPrevPage: pageNum > 1
    }
  });
});

// ========== ERROR HANDLING ==========

// 404 handler
app.use((req, res) => {
  res.status(404).json({
    error: config.NOT_FOUND_MESSAGE,
    path: req.path,
    method: req.method,
    timestamp: new Date().toISOString()
  });
});

// Global error handler
app.use((err, req, res, next) => {
  // Log error with appropriate detail level
  if (config.ENABLE_LOGGING) {
    const errorLog = {
      message: err.message,
      stack: config.DEBUG_MODE ? err.stack : undefined,
      url: req.url,
      method: req.method,
      ip: req.ip,
      userAgent: req.get('User-Agent'),
      timestamp: new Date().toISOString()
    };

    console.error('❌ Application Error:', errorLog);
  }

  // Determine status code
  const statusCode = err.statusCode || err.status || 500;

  // Prepare error response
  const errorResponse = {
    error: config.NODE_ENV === 'production' 
      ? config.PRODUCTION_ERROR_MESSAGE 
      : err.message,
    status: statusCode,
    timestamp: new Date().toISOString()
  };

  // Add stack trace in debug mode
  if (config.DEBUG_MODE && err.stack) {
    errorResponse.stack = err.stack;
  }

  res.status(statusCode).json(errorResponse);
});

// ========== SERVER STARTUP ==========

const server = app.listen(config.PORT, config.HOST, () => {
  console.log(`
  ███████╗███████╗ ██████╗██╗   ██╗██████╗ ███████╗
  ██╔════╝██╔════╝██╔════╝██║   ██║██╔══██╗██╔════╝
  ███████╗█████╗  ██║     ██║   ██║██████╔╝███████╗
  ╚════██║██╔══╝  ██║     ██║   ██║██╔══██╗╚════██║
  ███████║███████╗╚██████╗╚██████╔╝██║  ██║███████║
  ╚══════╝╚══════╝ ╚═════╝ ╚═════╝ ╚═╝  ╚═╝╚══════╝

  ${config.APP_NAME} v${config.APP_VERSION}
  ===================================================
  🌍 Environment: ${config.NODE_ENV}
  🚀 Server: http://${config.HOST}:${config.PORT}
  ⏱️  Rate Limit: ${config.ENABLE_RATE_LIMITING ? `${config.RATE_LIMIT_MAX_REQUESTS} req/${config.RATE_LIMIT_WINDOW_MS/60000}min` : 'Disabled'}
  🔒 CORS: ${config.ENABLE_CORS ? 'Enabled' : 'Disabled'}
  📝 Logging: ${config.ENABLE_LOGGING ? 'Enabled' : 'Disabled'}
  🐛 Debug: ${config.DEBUG_MODE ? 'Enabled' : 'Disabled'}
  ===================================================
  `);
});

// ========== GRACEFUL SHUTDOWN ==========

const shutdownSignals = ['SIGTERM', 'SIGINT', 'SIGHUP'];

shutdownSignals.forEach(signal => {
  process.on(signal, () => {
    console.log(`\n${signal} received, starting graceful shutdown...`);

    server.close(() => {
      console.log('✅ HTTP server closed gracefully');
      process.exit(0);
    });

    // Force shutdown after timeout
    setTimeout(() => {
      console.error('❌ Could not close connections in time, forcing shutdown');
      process.exit(1);
    }, config.SHUTDOWN_TIMEOUT_MS);
  });
});

// Handle uncaught exceptions
process.on('uncaughtException', (error) => {
  console.error('💥 Uncaught Exception:', error);
  server.close(() => {
    process.exit(1);
  });
});

process.on('unhandledRejection', (reason, promise) => {
  console.error('💥 Unhandled Rejection at:', promise, 'reason:', reason);
});

// ========== EXPORT FOR TESTING ==========
module.exports = { 
  app, 
  server, 
  config,
  shutdown: () => server.close()
};

