#!/usr/bin/env node

// Environment variable validation script
const dotenv = require('dotenv');
const fs = require('fs');
const path = require('path');

// Load environment variables
dotenv.config();

// Environment variable schema
const envSchema = {
  required: {
    development: ['NODE_ENV'],
    test: ['NODE_ENV'],
    production: ['NODE_ENV', 'ALLOWED_ORIGINS']
  },

  optional: {
    all: [
      'PORT', 'HOST', 'RATE_LIMIT_WINDOW_MS', 'RATE_LIMIT_MAX_REQUESTS',
      'RATE_LIMIT_MESSAGE', 'BODY_PARSER_LIMIT', 'ENABLE_RATE_LIMITING',
      'ENABLE_CORS', 'ENABLE_LOGGING', 'DEBUG_MODE', 'APP_NAME',
      'APP_VERSION', 'SHUTDOWN_TIMEOUT_MS', 'USER_MAX_LIMIT',
      'USER_DEFAULT_LIMIT', 'PRODUCTION_ERROR_MESSAGE', 'NOT_FOUND_MESSAGE',
      'DEMO_EMAIL_DOMAIN'
    ]
  },

  defaults: {
    PORT: '3000',
    HOST: 'localhost',
    NODE_ENV: 'development',
    RATE_LIMIT_WINDOW_MS: '900000',
    RATE_LIMIT_MAX_REQUESTS: '100',
    BODY_PARSER_LIMIT: '10kb',
    ENABLE_RATE_LIMITING: 'true',
    ENABLE_CORS: 'true',
    ENABLE_LOGGING: 'true',
    DEBUG_MODE: 'false',
    APP_NAME: 'Secure Express API',
    APP_VERSION: '1.0.0',
    SHUTDOWN_TIMEOUT_MS: '10000',
    USER_MAX_LIMIT: '100',
    USER_DEFAULT_LIMIT: '10'
  }
};

// Validation functions
const validators = {
  PORT: (value) => {
    const port = parseInt(value);
    return port >= 1 && port <= 65535 && Number.isInteger(port);
  },

  NODE_ENV: (value) => ['development', 'test', 'production'].includes(value),

  RATE_LIMIT_WINDOW_MS: (value) => {
    const ms = parseInt(value);
    return ms > 0 && Number.isInteger(ms);
  },

  RATE_LIMIT_MAX_REQUESTS: (value) => {
    const max = parseInt(value);
    return max > 0 && Number.isInteger(max);
  },

  ENABLE_RATE_LIMITING: (value) => ['true', 'false'].includes(value),
  ENABLE_CORS: (value) => ['true', 'false'].includes(value),
  ENABLE_LOGGING: (value) => ['true', 'false'].includes(value),
  DEBUG_MODE: (value) => ['true', 'false'].includes(value),

  SHUTDOWN_TIMEOUT_MS: (value) => {
    const timeout = parseInt(value);
    return timeout >= 0 && Number.isInteger(timeout);
  },

  USER_MAX_LIMIT: (value) => {
    const limit = parseInt(value);
    return limit > 0 && Number.isInteger(limit);
  },

  USER_DEFAULT_LIMIT: (value) => {
    const limit = parseInt(value);
    return limit > 0 && Number.isInteger(limit);
  }
};

console.log('🔍 Environment Variable Validation');
console.log('='.repeat(50));

// Get current environment
const nodeEnv = process.env.NODE_ENV || 'development';
console.log(`Environment: ${nodeEnv}`);

// Check .env.example file exists
const envExamplePath = path.join(__dirname, '.env.example');
if (fs.existsSync(envExamplePath)) {
  console.log('✓ .env.example template found');
} else {
  console.warn('⚠ .env.example template not found');
}

// Check .env file exists
const envPath = path.join(__dirname, '.env');
if (fs.existsSync(envPath)) {
  console.log('✓ .env file found');
} else {
  console.warn('⚠ .env file not found - using defaults');
}

// Validate required variables
const requiredVars = envSchema.required[nodeEnv] || [];
let missingVars = [];

requiredVars.forEach(variable => {
  if (!process.env[variable]) {
    missingVars.push(variable);
  }
});

if (missingVars.length > 0) {
  console.error(`\n❌ Missing required environment variables:`);
  missingVars.forEach(variable => {
    console.error(`   - ${variable}`);
  });
  process.exit(1);
} else {
  console.log('✓ All required environment variables present');
}

// Validate variable formats
const validationErrors = [];
const allVars = [...requiredVars, ...envSchema.optional.all];

allVars.forEach(variable => {
  if (process.env[variable] && validators[variable]) {
    if (!validators[variable](process.env[variable])) {
      validationErrors.push({
        variable,
        value: process.env[variable],
        message: `Invalid format for ${variable}`
      });
    }
  }
});

if (validationErrors.length > 0) {
  console.error(`\n❌ Environment variable validation errors:`);
  validationErrors.forEach(error => {
    console.error(`   - ${error.variable}: "${error.value}" - ${error.message}`);
  });
  process.exit(1);
} else {
  console.log('✓ All environment variables validated successfully');
}

// Show current configuration
console.log('\n📋 Current Configuration:');
console.log('-'.repeat(30));

const showVars = [
  'NODE_ENV', 'PORT', 'HOST', 'APP_NAME', 'APP_VERSION',
  'ENABLE_RATE_LIMITING', 'ENABLE_CORS', 'DEBUG_MODE',
  'RATE_LIMIT_MAX_REQUESTS', 'USER_MAX_LIMIT'
];

showVars.forEach(variable => {
  const value = process.env[variable] || envSchema.defaults[variable] || '(not set)';
  console.log(`  ${variable}: ${value}`);
});

// Check for potential issues
console.log('\n🔎 Potential Issues:');

const issues = [];

// Check if using default port
if (process.env.PORT === '3000') {
  issues.push('Using default port 3000 (consider changing for production)');
}

// Check if CORS allows all origins
if (process.env.ALLOWED_ORIGINS === '*') {
  issues.push('CORS allows all origins (*) - insecure for production');
}

// Check if debug mode is enabled in production
if (nodeEnv === 'production' && process.env.DEBUG_MODE === 'true') {
  issues.push('Debug mode enabled in production - security risk');
}

// Check if using default rate limits in production
if (nodeEnv === 'production') {
  const defaultRateLimit = process.env.RATE_LIMIT_MAX_REQUESTS === '100';
  const defaultWindow = process.env.RATE_LIMIT_WINDOW_MS === '900000';

  if (defaultRateLimit && defaultWindow) {
    issues.push('Using default rate limiting settings in production');
  }
}

if (issues.length > 0) {
  issues.forEach(issue => console.warn(`⚠ ${issue}`));
} else {
  console.log('✓ No major issues detected');
}

console.log('\n✅ Environment validation completed successfully');
console.log('='.repeat(50));

