      email: req.body.email, // Already normalized by express-validator
      password: req.body.password, // Should be hashed before storage
      age: req.body.age,
      website: req.body.website,
      phone: req.body.phone,
      createdAt: new Date(),
      ipAddress: req.ip // Log IP for security monitoring
    };

    // In real application, hash password here
    // userData.password = await bcrypt.hash(userData.password, 10);

    // Save to database (use parameterized queries!)

    res.status(201).json({
      success: true,
      message: 'User created successfully',
      data: {
        id: '12345', // Generated ID from database
        name: userData.name,
        email: userData.email
      },
      meta: {
        timestamp: new Date().toISOString()
      }
    });
  } catch (error) {
    console.error('User creation error:', error);
    res.status(500).json({
      error: 'Internal Server Error',
      message: 'Failed to create user'
    });
  }
});

// GET /users/:id - Get user by ID with validation
router.get('/users/:id', validate(idParamValidation), async (req, res) => {
  try {
    const userId = req.params.id; // Already sanitized

    // Fetch user from database using parameterized query
    // const user = await db.query('SELECT * FROM users WHERE id = $1', [userId]);

    res.json({
      success: true,
      data: {
        id: userId,
        name: 'Example User',
        email: 'user@example.com'
      }
