// Fully Configurable Express Application
// All hardcoded values moved to environment variables

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const cors = require('cors');

// Load environment variables
require('dotenv').config();

const app = express();

// Configuration from environment variables with sensible defaults
const config = {
  port: parseInt(process.env.PORT) || 3000,
  nodeEnv: process.env.NODE_ENV || 'development',

  // Security configuration
  corsOrigin: process.env.CORS_ORIGIN || '*',
  rateLimitWindowMs: parseInt(process.env.RATE_LIMIT_WINDOW_MS) || (15 * 60 * 1000), // 15 minutes default
  rateLimitMax: parseInt(process.env.RATE_LIMIT_MAX) || 100,
  requestSizeLimit: process.env.REQUEST_SIZE_LIMIT || '10kb',

  // Application configuration
  maxQueryLimit: parseInt(process.env.MAX_QUERY_LIMIT) || 100,
  apiVersion: process.env.API_VERSION || 'v1',
  serverTimeout: parseInt(process.env.SERVER_TIMEOUT) || 30000, // 30 seconds default

  // Feature flags
  enableCors: process.env.ENABLE_CORS !== 'false', // enabled by default
  enableRateLimiting: process.env.ENABLE_RATE_LIMITING !== 'false', // enabled by default
  enableSecurityHeaders: process.env.ENABLE_SECURITY_HEADERS !== 'false', // enabled by default
};

// Security middleware - conditionally enabled
if (config.enableSecurityHeaders) {
  app.use(helmet());
}

// CORS middleware - conditionally enabled with configurable origin
if (config.enableCors) {
  app.use(cors({
    origin: config.corsOrigin,
    methods: ['GET', 'POST', 'PUT', 'DELETE', 'OPTIONS'],
    allowedHeaders: ['Content-Type', 'Authorization', 'X-API-Key'],
    credentials: true,
  }));
}

// Rate limiting - conditionally enabled
if (config.enableRateLimiting) {
  const limiter = rateLimit({
    windowMs: config.rateLimitWindowMs,
    max: config.rateLimitMax,
    message: process.env.RATE_LIMIT_MESSAGE || 'Too many requests from this IP, please try again later.',
    standardHeaders: true,
    legacyHeaders: false,
    skipFailedRequests: false,
    skipSuccessfulRequests: false,
  });
  app.use(limiter);
}

// Body parsing with configurable limits
app.use(express.json({ limit: config.requestSizeLimit }));
app.use(express.urlencoded({ 
  extended: true, 
  limit: config.requestSizeLimit 
}));

// Request timeout middleware
app.use((req, res, next) => {
  req.setTimeout(config.serverTimeout, () => {
    res.status(408).json({ 
      error: 'Request timeout',
      message: 'Request took too long to process'
    });
  });
  next();
});

// Request logging middleware with environment-specific logging
app.use((req, res, next) => {
  const logLevel = process.env.LOG_LEVEL || 'info';
  if (logLevel === 'debug') {
    console.debug(`${new Date().toISOString()} - ${req.method} ${req.url} - ${req.ip}`);
  } else {
    console.log(`${new Date().toISOString()} - ${req.method} ${req.url}`);
  }
  next();
});

// Health check endpoint with configuration info
app.get('/health', (req, res) => {
  const healthInfo = {
    status: 'ok',
    timestamp: new Date().toISOString(),
    environment: config.nodeEnv,
    version: config.apiVersion,
    config: config.nodeEnv === 'development' ? {
      rateLimitEnabled: config.enableRateLimiting,
      corsEnabled: config.enableCors,
      securityHeadersEnabled: config.enableSecurityHeaders,
    } : undefined, // Don't expose config in production
  };
  res.json(healthInfo);
});

// Users endpoint with fully configurable validation
app.get('/users', (req, res, next) => {
  try {
    // Configurable input validation
    const { limit, offset } = req.query;

    if (limit) {
      const limitValue = parseInt(limit);
      if (isNaN(limitValue) || limitValue > config.maxQueryLimit || limitValue < 1) {
        return res.status(400).json({ 
          error: 'Invalid limit parameter',
          message: `Limit must be between 1 and ${config.maxQueryLimit}`,
          maxAllowed: config.maxQueryLimit
        });
      }
    }

    if (offset && isNaN(parseInt(offset))) {
      return res.status(400).json({ 
        error: 'Invalid offset parameter',
        message: 'Offset must be a number'
      });
    }

    // Mock data - in production, this would come from a database
    // Database configuration would also come from environment variables
    const users = [
      { id: 1, name: 'Alice', email: process.env.DEMO_USER_1_EMAIL || 'alice@example.com' },
      { id: 2, name: 'Bob', email: process.env.DEMO_USER_2_EMAIL || 'bob@example.com' },
    ];

    // Apply pagination if specified
    const result = limit ? users.slice(0, parseInt(limit)) : users;

    res.json({
      data: result,
      pagination: {
        total: users.length,
        limit: limit ? parseInt(limit) : null,
        offset: offset ? parseInt(offset) : 0
      },
      version: config.apiVersion
    });
  } catch (error) {
    next(error);
  }
});

// 404 handler
app.use((req, res) => {
  res.status(404).json({ 
    error: 'Not found',
    message: `Cannot ${req.method} ${req.url}`,
    version: config.apiVersion
  });
});

// Global error handler with environment-specific error details
app.use((err, req, res, next) => {
  const statusCode = err.statusCode || 500;
  const errorId = Math.random().toString(36).substr(2, 9); // Generate error ID for tracking

  // Log error with context
  console.error(`Error [${errorId}]:`, {
    message: err.message,
    stack: config.nodeEnv === 'development' ? err.stack : undefined,
    url: req.url,
    method: req.method,
    ip: req.ip,
    timestamp: new Date().toISOString()
  });

  const response = {
    error: 'Internal server error',
    message: config.nodeEnv === 'production' ? undefined : err.message,
    errorId: errorId, // For support reference
    timestamp: new Date().toISOString(),
    version: config.apiVersion
  };

  res.status(statusCode).json(response);
});

// Start server with configuration
const server = app.listen(config.port, () => {
  console.log(`Server configuration:`);
  console.log(`- Port: ${config.port}`);
  console.log(`- Environment: ${config.nodeEnv}`);
  console.log(`- API Version: ${config.apiVersion}`);
  console.log(`- Rate Limiting: ${config.enableRateLimiting ? 'Enabled' : 'Disabled'}`);
  console.log(`- CORS: ${config.enableCors ? 'Enabled' : 'Disabled'}`);
  console.log(`- Security Headers: ${config.enableSecurityHeaders ? 'Enabled' : 'Disabled'}`);
  console.log(`- Request Size Limit: ${config.requestSizeLimit}`);
  console.log(`- Server Timeout: ${config.serverTimeout}ms`);
  console.log(`Server running on port ${config.port}`);
});

// Handle graceful shutdown
process.on('SIGTERM', () => {
  console.log('SIGTERM signal received: closing HTTP server');
  server.close(() => {
    console.log('HTTP server closed');
    process.exit(0);
  });
});

process.on('SIGINT', () => {
  console.log('SIGINT signal received: closing HTTP server');
  server.close(() => {
    console.log('HTTP server closed');
    process.exit(0);
  });
});

module.exports = {
  app,
  config,
  server
};

