// Secure application with environment variables
require('dotenv').config(); // Load environment variables from .env file

const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');

const app = express();

// Validate required environment variables
const requiredEnvVars = ['NODE_ENV'];
requiredEnvVars.forEach(varName => {
  if (!process.env[varName]) {
    console.warn(`Warning: Environment variable ${varName} is not set`);
  }
});

// Configuration from environment variables
const config = {
  port: parseInt(process.env.PORT || '3000', 10),
  nodeEnv: process.env.NODE_ENV || 'development',
  allowedOrigins: process.env.ALLOWED_ORIGINS 
    ? process.env.ALLOWED_ORIGINS.split(',') 
    : ['http://localhost:3000'],
  rateLimitWindowMs: parseInt(process.env.RATE_LIMIT_WINDOW_MS || '900000', 10), // 15 minutes default
  rateLimitMax: parseInt(process.env.RATE_LIMIT_MAX || '100', 10),
  jsonSizeLimit: process.env.JSON_SIZE_LIMIT || '10kb',

  // Sample user data - could be loaded from env or database
  users: process.env.SAMPLE_USERS 
    ? JSON.parse(process.env.SAMPLE_USERS)
    : [
        { id: 1, name: 'Alice' }, // Email removed for privacy
        { id: 2, name: 'Bob' },
      ]
};

// Security middleware
app.use(helmet());
app.use(cors({
  origin: config.allowedOrigins,
  credentials: true
}));

// Rate limiting
const limiter = rateLimit({
  windowMs: config.rateLimitWindowMs,
  max: config.rateLimitMax
});
app.use(limiter);

// Parse JSON with configurable size limit
app.use(express.json({ limit: config.jsonSizeLimit }));

// Health endpoint with environment info
app.get('/health', (req, res) => {
  res.json({ 
    status: 'ok', 
    timestamp: new Date().toISOString(),
    environment: config.nodeEnv,
    // Don't expose sensitive config in production
    config: config.nodeEnv === 'development' ? {
      port: config.port,
      rateLimit: {
        windowMs: config.rateLimitWindowMs,
        max: config.rateLimitMax
      }
    } : undefined
  });
});

// Users endpoint - consider adding authentication
app.get('/users', (req, res) => {
  // In production, this should require authentication
  // and fetch from a proper database
  res.json(config.users);
});

// Error handling middleware
app.use((err, req, res, next) => {
  console.error(`[${new Date().toISOString()}] Error:`, err.message);

  res.status(err.status || 500).json({ 
    error: 'Internal server error',
    // Only expose error details in development
    message: config.nodeEnv === 'development' ? err.message : undefined,
    // Add request ID for tracing in production
    requestId: req.id || Date.now().toString(36)
  });
});

// 404 handler
app.use((req, res) => {
  res.status(404).json({ 
    error: 'Not found',
    path: req.path
  });
});

// Start server with error handling
const server = app.listen(config.port, () => {
  console.log(`[${config.nodeEnv}] Server running on port ${config.port}`);
  console.log(`Environment: ${config.nodeEnv}`);
  console.log(`Rate limit: ${config.rateLimitMax} requests per ${config.rateLimitWindowMs/60000} minutes`);
});

// Handle server errors
server.on('error', (err) => {
  console.error('Server failed to start:', err);
  process.exit(1);
});

// Graceful shutdown
process.on('SIGTERM', () => {
  console.log('SIGTERM received, shutting down gracefully');
  server.close(() => {
    console.log('Server closed');
    process.exit(0);
  });
});

module.exports = { app, config, server };

