// Error handling middleware
app.use((err, req, res, next) => {
    const isProduction = process.env.NODE_ENV === 'production';
    const logErrors = process.env.LOG_ERRORS !== 'false'; // Default to true

    if (logErrors) {
        const errorMessage = isProduction 
            ? `Error: ${err.message}` 
            : `Error: ${err.stack}`;

        if (logLevel === 'error' || logLevel === 'warn' || logLevel === 'info' || logLevel === 'debug') {
            console.error(errorMessage);
        }
    }

    // Configurable error response
    const defaultErrorCode = parseInt(process.env.DEFAULT_ERROR_CODE) || 500;
    const errorResponse = {
        error: process.env.CUSTOM_ERROR_MESSAGE || 'An unexpected error occurred',
        ...(isProduction && process.env.HIDE_ERROR_DETAILS === 'true' ? {} : { details: err.message })
    };

    res.status(err.status || defaultErrorCode).json(errorResponse);
});

// 404 handler with configurable message
app.use((req, res) => {
    const notFoundCode = parseInt(process.env.NOT_FOUND_ERROR_CODE) || 404;
    const notFoundMessage = process.env.NOT_FOUND_MESSAGE || 'Route not found';
    res.status(notFoundCode).json({ error: notFoundMessage });
});

