#!/usr/bin/env node

// Migration script to help move from hardcoded values to environment variables

const fs = require('fs');

console.log('🔄 Migration Helper: Move Hardcoded Values to Environment Variables');
console.log('='.repeat(80));

// Read original app.js
try {
    const originalContent = fs.readFileSync('app.js', 'utf8');

    console.log('\n📋 Current Configuration in app.js:');
    console.log('='.repeat(80));

    // Find port
    const portMatch = originalContent.match(/app\.listen\((\d+)/);
    if (portMatch) {
        console.log(`🔌 Port: ${portMatch[1]} (hardcoded)`);
        console.log(`   Recommendation: Change to process.env.PORT || ${portMatch[1]}`);
    }

    // Find any potential API keys or secrets (basic check)
    const potentialSecrets = originalContent.match(/['"](sk_[^'"]+|AKIA[^'"]+|api[_-]?key[^'"]+)['"]/gi);
    if (potentialSecrets && potentialSecrets.length > 0) {
        console.log('\n🔐 Potential Secrets Found:');
        potentialSecrets.forEach(secret => {
            console.log(`   ⚠️  "${secret.substring(0, 20)}..." (should be environment variable)`);
        });
    }

    // Find URLs
    const urls = originalContent.match(/['"](https?:\/\/[^'"]+)['"]/g);
    if (urls && urls.length > 0) {
        console.log('\n🌐 Hardcoded URLs:');
        urls.forEach(url => {
            console.log(`   ${url}`);
        });
    }

    console.log('\n' + '='.repeat(80));
    console.log('💡 Migration Steps:');
    console.log('='.repeat(80));

    console.log('\n1. Update app.js:');
    console.log('   Replace: app.listen(3000, () => {');
    console.log('   With:    const PORT = process.env.PORT || 3000;');
    console.log('            app.listen(PORT, () => {');

    console.log('\n2. Create/update .env file:');
    console.log('   Copy .env.example to .env');
    console.log('   Configure values for your environment');

    console.log('\n3. Install dotenv (optional but recommended):');
    console.log('   npm install dotenv');
    console.log('   Add to top of app.js: require("dotenv").config();');

    console.log('\n4. Update package.json scripts:');
    console.log('   Add "start": "node app.js"');
    console.log('   Add "dev": "NODE_ENV=development node app.js"');

    console.log('\n5. Consider using the secure version:');
    console.log('   The file secure_app.js already implements all best practices');
    console.log('   You can use it as a starting point for your application');

    console.log('\n' + '='.repeat(80));
    console.log('📦 Quick Migration Template:');
    console.log('='.repeat(80));

    console.log(`
// Updated app.js with environment variables
require('dotenv').config(); // Optional: for local .env file loading

const express = require('express');
const app = express();

const PORT = process.env.PORT || 3000;

app.get('/health', (req, res) => {
  res.json({ 
    status: 'ok', 
    timestamp: new Date().toISOString(),
    version: process.env.APP_VERSION || '1.0.0'
  });
});

app.get('/users', (req, res) => {
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});

app.listen(PORT, () => {
  console.log(\`Server running on port \${PORT}\`);
});

module.exports = app;
`);

} catch (error) {
    console.error('❌ Error reading app.js:', error.message);
}

console.log('\n' + '='.repeat(80));
console.log('✅ Migration Complete!');
console.log('='.repeat(80));
